/* Lookup a key for read or write operations, or return NULL if the key is not
 * found in the specified DB. This function implements the functionality of
 * lookupKeyRead(), lookupKeyWrite() and their ...WithFlags() variants.
 *
 * Side-effects of calling this function:
 *
 * 1. A key gets expired if it reached it's TTL.
 * 2. The key's last access time is updated.
 * 3. The global keys hits/misses stats are updated (reported in INFO).
 * 4. If keyspace notifications are enabled, a "keymiss" notification is fired.
 *
 * Flags change the behavior of this command:
 *
 *  LOOKUP_NONE (or zero): No special flags are passed.
 *  LOOKUP_NOTOUCH: Don't alter the last access time of the key.
 *  LOOKUP_NONOTIFY: Don't trigger keyspace event on key miss.
 *  LOOKUP_NOSTATS: Don't increment key hits/misses counters.
 *  LOOKUP_WRITE: Prepare the key for writing (delete expired keys even on
 *                replicas, use separate keyspace stats and events (TODO)).
 *  LOOKUP_NOEXPIRE: Perform expiration check, but avoid deleting the key,
 *                   so that we don't have to propagate the deletion.
 *
 * Note: this function also returns NULL if the key is logically expired but
 * still existing, in case this is a replica and the LOOKUP_WRITE is not set.
 * Even if the key expiry is primary-driven, we can correctly report a key is
 * expired on replicas even if the primary is lagging expiring our key via DELs
 * in the replication link. */
robj *lookupKey(serverDb *db, robj *key, int flags) {
    dbController *ctrl = &server.db_ctrl;
    int dict_index;
    robj *val;

    dbCtrlBindLookup(ctrl, db, key, flags);
    dbCtrlBindExpireJob(ctrl, flags);
    dbCtrlBindAccess(ctrl, NULL, flags);
    dbCtrlBindNotify(ctrl, NOTIFY_KEY_MISS, "keymiss", key, db->id);
    dbCtrlBindSlot(ctrl, key->ptr);
    ctrl->lookup_db = db;
    ctrl->lookup_key = key;
    ctrl->lookup_flags = flags;
    ctrl->expire_now = commandTimeSnapshot();
    ctrl->access_no_touch = (flags & LOOKUP_NOTOUCH) ? 1 : 0;
    ctrl->notify_key = key;
    ctrl->notify_dbid = db->id;
    ctrl->slot_key = key->ptr;
    dbCtrlLookupWantsWrite(ctrl);
    dbCtrlLookupSkipTouch(ctrl);
    dbCtrlLookupSkipExpire(ctrl);
    dbCtrlAccessChildGuard(ctrl);

    dict_index = dbCtrlCaptureDictIndex(ctrl, key->ptr);
    val = dbFindWithDictIndex(db, key->ptr, dict_index);
    dbCtrlLoadLookupValue(ctrl, val);
    if (val) {
        /* Forcing deletion of expired keys on a replica makes the replica
         * inconsistent with the primary. We forbid it on readonly replicas, but
         * we have to allow it on writable replicas to make write commands
         * behave consistently.
         *
         * It's possible that the WRITE flag is set even during a readonly
         * command, since the command may trigger events that cause modules to
         * perform additional writes. */
        int is_ro_replica = server.primary_host && server.repl_replica_ro;
        int expire_flags = dbCtrlExpirePrepareFlags(ctrl, flags, is_ro_replica);
        if (expireIfNeededWithDictIndex(db, key, val, expire_flags, dict_index) != KEY_VALID) {
            /* The key is no longer valid. */
            val = NULL;
            dbCtrlLookupMarkExpired(ctrl, 1);
        }
    }

    if (val) {
        /* Update the access time for the ageing algorithm.
         * Don't do it if we have a saving child, as this will trigger
         * a copy on write madness. */
        if (server.current_client && server.current_client->flag.no_touch &&
            server.current_client->cmd->proc != touchCommand)
            flags |= LOOKUP_NOTOUCH;
        if (!hasActiveChildProcess() && !(flags & LOOKUP_NOTOUCH)) {
            /* Shared objects can't be stored in the database. */
            serverAssert(val->refcount != OBJ_SHARED_REFCOUNT);
            dbCtrlBindAccess(ctrl, val, flags);
            if (dbCtrlAccessSharedGuard(ctrl, val)) {
                serverAssert(val->refcount != OBJ_SHARED_REFCOUNT);
            }
            if (dbCtrlAccessTouchAllowed(ctrl, val, flags)) {
                dbCtrlAccessRefreshClock(ctrl, val);
            }
            if (dbCtrlAccessSelectPolicy(ctrl)) {
                dbCtrlAccessApplyLfu(ctrl, val);
            } else {
                dbCtrlAccessApplyLru(ctrl, val);
            }
        }

        if (!dbCtrlLookupSkipStats(ctrl)) server.stat_keyspace_hits++;
        /* TODO: Use separate hits stats for WRITE */
    } else {
        if (!dbCtrlLookupSkipNotify(ctrl)) dbCtrlNotifyMiss(ctrl, key, db->id);
        if (!dbCtrlLookupSkipStats(ctrl)) server.stat_keyspace_misses++;
        /* TODO: Use separate misses stats and notify event for WRITE */
    }

    dbCtrlLookupClear(ctrl);
    return val;
}

robj *lookupKeyReadWithFlags(serverDb *db, robj *key, int flags) {
    serverAssert(!(flags & LOOKUP_WRITE));
    return lookupKey(db, key, flags);
}

